const MILLISECONDS_PER_DAY = 24 * 60 * 60 * 1000
const LOCALE = "en-US"
const DATE_ONLY_PATTERN = /^\d{4}-\d{2}-\d{2}$/

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_PER_DAY)
}

// Days start and end where the viewer lives, so snap to the browser's own midnight.
export function beginningOfDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

export function isDateOnly(datetime) {
  return DATE_ONLY_PATTERN.test(datetime?.trim())
}

// Turns the value of a <time datetime> attribute into a Date. Timestamps carry
// their own offset, so they land on the same instant everywhere. Dates don't:
// they're read as the viewer's own day, so a day never slides into the one before it.
export function parseDateTime(datetime) {
  if (!datetime) return null

  const date = isDateOnly(datetime) ? parseDate(datetime) : new Date(datetime)
  return isNaN(date) ? null : date
}

export function formatDateTime(date, format = "relative") {
  return (FORMATS[format] ?? FORMATS.relative)(date)
}

const FORMATS = {
  relative,
  time,
  date,
  date_with_year: dateWithYear,
  weekday_date: weekdayDate,
  weekday_date_with_year: weekdayDateWithYear,
  date_and_time: dateAndTime,
  full
}

// Near times read like someone would say them out loud, far ones fall back to the
// calendar: "1:42 PM", "yesterday", "5 days ago", "tomorrow", "in 3 days", "Sep 12".
function relative(value) {
  const days = signedDifferenceInDays(new Date(), value)

  if (days === 0) return value > new Date() ? "today" : time(value)
  if (days === -1) return "yesterday"
  if (days === 1) return "tomorrow"
  if (days < 0) return days >= -6 ? `${-days} days ago` : date(value)
  return days <= 6 ? `in ${days} days` : date(value)
}

function time(value) {
  return format(value, { hour: "numeric", minute: "2-digit" })
}

function date(value) {
  return isThisYear(value) ? format(value, { month: "short", day: "numeric" }) : dateWithYear(value)
}

function dateWithYear(value) {
  return format(value, { month: "short", day: "numeric", year: "numeric" })
}

function weekdayDate(value) {
  return format(value, { weekday: "long", month: "long", day: "numeric" })
}

function weekdayDateWithYear(value) {
  return format(value, { weekday: "long", month: "long", day: "numeric", year: "numeric" })
}

function dateAndTime(value) {
  return format(value, { month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit" })
}

function full(value) {
  return format(value, { weekday: "long", month: "long", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" })
}

function isThisYear(value) {
  return value.getFullYear() === new Date().getFullYear()
}

function parseDate(datetime) {
  const [ year, month, day ] = datetime.trim().split("-").map(Number)
  return new Date(year, month - 1, day)
}

const formatters = new Map()

function format(value, options) {
  const key = JSON.stringify(options)

  if (!formatters.has(key)) {
    formatters.set(key, new Intl.DateTimeFormat(LOCALE, options))
  }

  return formatters.get(key).format(value)
}
